source /tmp/explore/sqlite-inspect/run.sh
mkdir -p /tmp/explore/sqlite-inspect/pk && cd /tmp/explore/sqlite-inspect/pk
rm -f p.db
python3 - <<'PY'
import sqlite3
c=sqlite3.connect('/tmp/explore/sqlite-inspect/pk/p.db')
c.executescript("""
CREATE TABLE pk_inline (id INTEGER PRIMARY KEY, x TEXT);
CREATE TABLE pk_autoinc (id INTEGER PRIMARY KEY AUTOINCREMENT, x TEXT);
CREATE TABLE pk_table (id INTEGER, x TEXT, PRIMARY KEY (id));
CREATE TABLE pk_comp (a INTEGER, b TEXT, PRIMARY KEY (a, b));
CREATE TABLE pk_desc (a INTEGER, b TEXT, PRIMARY KEY (a DESC, b ASC));
CREATE TABLE pk_named (a INTEGER, b TEXT, CONSTRAINT my_pk PRIMARY KEY (a));
CREATE TABLE pk_conflict (a INTEGER PRIMARY KEY ON CONFLICT REPLACE, b TEXT);
CREATE TABLE pk_text (a TEXT PRIMARY KEY, b TEXT);
CREATE TABLE pk_norowid (a TEXT, b TEXT, PRIMARY KEY (a)) WITHOUT ROWID;
CREATE TABLE pk_strict (a INTEGER PRIMARY KEY, b TEXT NOT NULL) STRICT;
CREATE TABLE pk_both (a INTEGER PRIMARY KEY, b TEXT) WITHOUT ROWID;
CREATE TABLE pk_none (a INTEGER, b TEXT);
CREATE TABLE pk_collate (a TEXT, PRIMARY KEY (a COLLATE NOCASE));
CREATE TABLE pk_expr_ai (id INTEGER PRIMARY KEY DESC, x TEXT);
""")
c.commit(); c.close()
PY
run schema inspect -u "sqlite://p.db"

