CREATE TABLE t (a INTEGER, b TEXT, c TEXT UNIQUE, d TEXT, e INTEGER);
CREATE INDEX idx_a ON t (a);
CREATE UNIQUE INDEX idx_b ON t (b);
CREATE INDEX idx_ab ON t (a, b);
CREATE INDEX idx_desc ON t (a DESC, b ASC);
CREATE INDEX idx_partial ON t (a) WHERE a > 10;
CREATE INDEX idx_expr ON t (lower(b));
CREATE INDEX idx_expr2 ON t (a + e, b);
CREATE INDEX idx_coll ON t (b COLLATE NOCASE);
CREATE UNIQUE INDEX idx_partial_u ON t (d) WHERE d IS NOT NULL;
CREATE TABLE t2 (a INTEGER, b TEXT, UNIQUE (a, b));
CREATE TABLE t3 (a INTEGER PRIMARY KEY, b TEXT UNIQUE);
""")
c.commit(); c.close()
PY
